import { createHash } from "node:crypto";
import { createReadStream, readFileSync } from "node:fs";
import { pipeline } from "node:stream/promises";

import type * as semver from "semver";

import type { Logger } from "../logging/logger";

/**
 * SHA-256 digests of the Coder CLI binaries in releases that are not signed
 * with the current release key, keyed by version (major.minor.patch) and then
 * by binary name (for example coder-linux-amd64). Generated by
 * scripts/generate-release-digests.mts.
 */
export type Digests = Record<string, Record<string, string>>;

/**
 * How a binary compares with the release it claims to be: the same digest, a
 * different digest, or a release and platform with no digest.
 */
type ReleaseDigestResult = "match" | "mismatch" | "unlisted";

export function readReleaseDigests(digestsPath: string): Digests {
	return JSON.parse(readFileSync(digestsPath, "utf8")) as Digests;
}

export class ReleaseDigests {
	constructor(
		private readonly digests: Digests,
		private readonly logger: Logger,
	) {}

	/**
	 * Compare the file at cliPath with the released binName of this version. A
	 * genuine binary of another version or platform does not match.
	 */
	public async check(
		cliPath: string,
		version: semver.SemVer,
		binName: string,
	): Promise<ReleaseDigestResult> {
		const release = `${version.major}.${version.minor}.${version.patch}`;
		const expected = this.digests[release]?.[binName];
		if (!expected) {
			this.logger.info("No release digest for", binName, release);
			return "unlisted";
		}
		const hash = createHash("sha256");
		await pipeline(createReadStream(cliPath), hash);
		const actual = hash.digest("hex");
		if (actual !== expected) {
			this.logger.warn(
				`Digest of ${cliPath} is ${actual}, but ${binName} ${release} was released as ${expected}`,
			);
			return "mismatch";
		}
		this.logger.info("Binary matches the release digest for", binName, release);
		return "match";
	}
}
